pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address attacker, uint256 sendAmount) public {
        vm.assume(attacker != address(0));
        sendAmount = bound(sendAmount, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        (bool s,) = address(c).call{value: 1 ether}("");
        assertTrue(s);

        Adversary adv = new Adversary();

        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        bytes memory data = "";
        try c.sendMoney(address(adv), sendAmount, data) {
        } catch {
        }

        uint256 balBefore = address(c).balance;
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balAfter = address(c).balance;

        assertTrue(balAfter == balBefore);
    }
}

contract Adversary {
    receive() external payable {}
    fallback() external payable {}
}
